dora_rts_physical_hr_identity_and_access_what_if(Profile, OverriddenKey, NewValue, NewStatus) :-
    dora_rts_physical_hr_identity_and_access_input_problems(Profile, Problems),
    what_if_step(Problems, Profile, OverriddenKey, NewValue, NewStatus).

what_if_step([Problem|Problems], _, _, _, input_problems([Problem|Problems])).
what_if_step([], Profile, OverriddenKey, NewValue, NewStatus) :-
    without_key(Profile, OverriddenKey, Kept),
    append(Kept, [attribute(OverriddenKey, NewValue)], Hypothesis),
    dora_rts_physical_hr_identity_and_access_status(Hypothesis, NewStatus).

without_key([], _, []).
without_key([attribute(ElementKey, _)|Elements], Key, Kept) :-
    ElementKey == Key,
    without_key(Elements, Key, Kept).
without_key([attribute(ElementKey, Value)|Elements], Key, [attribute(ElementKey, Value)|Kept]) :-
    ElementKey \== Key,
    without_key(Elements, Key, Kept).

dora_rts_physical_hr_identity_and_access_compliance_check(Profile, Duty, Verdict) :-
    dora_rts_physical_hr_identity_and_access_input_problems(Profile, Problems),
    compliance_with_problems(Problems, Profile, Duty, Verdict).

compliance_with_problems([Problem|Problems], _, _, input_problems([Problem|Problems])).
compliance_with_problems([], Profile, Duty, Verdict) :-
    dora_rts_physical_hr_identity_and_access_checklist(Profile, [GateItem|DutyItems]),
    findall(KnownDuty, member(item(KnownDuty, _, _), DutyItems), KnownDuties),
    memberd_t(Duty, KnownDuties, IsDuty),
    compliance_for_duty(IsDuty, GateItem, DutyItems, Profile, Duty, Verdict).

compliance_for_duty(false, _, _, _, Duty, input_problems([unknown_key(Duty)])).
compliance_for_duty(true, item(_, GateStatus, _), DutyItems, Profile, Duty, Verdict) :-
    gate_compliance(GateStatus, DutyItems, Profile, Duty, Verdict).

gate_compliance(unmet(simplified_framework_entity), _, _, _, simplified_framework_entity) :-
    implements(eu_reg_2022_2554_art_16_1).
gate_compliance(unknown(Keys), _, _, _, indeterminate(Keys)) :-
    implements(eu_reg_2022_2554_art_16_1).
gate_compliance(met, DutyItems, Profile, Duty, Verdict) :-
    implements(eu_reg_2022_2554_art_16_1),
    member(item(Duty, Status, Citation), DutyItems),
    duty_compliance(Status, Citation, Profile, Verdict).

duty_compliance(met, cite(_), _, satisfied).
duty_compliance(unmet(_), cite(_), _, violated).
duty_compliance(unknown([Key]), cite(_), Profile, indeterminate([Key])) :-
    profile_lacks(Profile, Key).
duty_compliance(unknown([Key]), cite(CitationKey), Profile, needs_legal_review(open_textured(Key, cite(CitationKey)), [inputs_relied_on(Pairs)])) :-
    profile_get(Profile, Key, unsure),
    relied_on_pairs(Profile, Pairs).

relied_on_pairs(Profile, Pairs) :-
    dora_rts_physical_hr_identity_and_access_profile_keys(Keys),
    findall(Key - Value, (member(Key, Keys), profile_has(Profile, Key), profile_get(Profile, Key, Value)), Pairs).

duty_attributes_true(Attributes) :-
    dora_rts_physical_hr_identity_and_access_profile_keys([_|DutyKeys]),
    findall(attribute(Key, true), member(Key, DutyKeys), Attributes).

test(the_schema_has_thirty_seven_keys) :-
    dora_rts_physical_hr_identity_and_access_profile_keys(Keys),
    length(Keys, 37).
test(what_if_the_entity_is_not_an_article_16_1_entity) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_what_if([attribute(financial_entity_is_article_16_1_entity, true)|Attributes], financial_entity_is_article_16_1_entity, false, complete).
test(what_if_the_entity_is_an_article_16_1_entity) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_what_if([attribute(financial_entity_is_article_16_1_entity, false)|Attributes], financial_entity_is_article_16_1_entity, true, simplified_framework_entity).
test(what_if_a_duty_is_not_performed_has_one_answer) :-
    duty_attributes_true(Attributes),
    findall(Status, dora_rts_physical_hr_identity_and_access_what_if([attribute(financial_entity_is_article_16_1_entity, false)|Attributes], access_control_policy_contains_segregation_of_duties, false, Status), Statuses),
    Statuses == [incomplete].
test(what_if_a_bad_value_is_an_input_problem) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_what_if([attribute(financial_entity_is_article_16_1_entity, false)|Attributes], financial_entity_is_article_16_1_entity, unsure, input_problems([wrong_type(financial_entity_is_article_16_1_entity)])).
test(a_performed_duty_is_satisfied) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false)|Attributes], segregation_of_duties, satisfied).
test(a_duty_not_performed_is_violated) :-
    duty_attributes_true(Attributes),
    without_key(Attributes, access_control_policy_contains_segregation_of_duties, Kept),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false), attribute(access_control_policy_contains_segregation_of_duties, false)|Kept], segregation_of_duties, violated).
test(an_absent_duty_is_asked) :-
    duty_attributes_true(Attributes),
    without_key(Attributes, access_control_policy_contains_segregation_of_duties, Kept),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false)|Kept], segregation_of_duties, indeterminate([access_control_policy_contains_segregation_of_duties])).
test(an_unsure_duty_goes_to_a_lawyer) :-
    duty_attributes_true(Attributes),
    without_key(Attributes, access_control_policy_contains_segregation_of_duties, Kept),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false), attribute(access_control_policy_contains_segregation_of_duties, unsure)|Kept], segregation_of_duties, needs_legal_review(open_textured(access_control_policy_contains_segregation_of_duties, cite(eu_reg_2024_1774_art_21_b)), [inputs_relied_on(Pairs)])),
    length(Pairs, 37).
test(the_gate_defeats_the_obligation) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, true)|Attributes], segregation_of_duties, simplified_framework_entity).
test(an_absent_gate_is_asked_first) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_compliance_check(Attributes, segregation_of_duties, indeterminate([financial_entity_is_article_16_1_entity])).
test(an_unknown_duty_is_an_input_problem) :-
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false)], colour, input_problems([unknown_key(colour)])).
test(a_bad_profile_is_an_input_problem) :-
    dora_rts_physical_hr_identity_and_access_compliance_check(not_a_list, segregation_of_duties, input_problems([wrong_type(profile)])).

test(a_performed_duty_is_not_violated, fail) :-
    duty_attributes_true(Attributes),
    dora_rts_physical_hr_identity_and_access_compliance_check([attribute(financial_entity_is_article_16_1_entity, false)|Attributes], segregation_of_duties, violated).
